### What is the problem this request aims to solve?

Recursively call a function with each node in given root-node. 

There could be also "upward"-version, which executes function from given node to all its ancestors up until absolute root-node.

### How do you suggest we solve this problem?

`flexpanel_node_execute(root, function)` where it iterates through all nodes in the tree-structure.
The function could have arguments `function(node, data) { }`. 
The iteration order matters, I would assume child-nodes should be executed first from 0 to N. Look below example functions.

In below example I also include "result"-argument, which is returned. This is also optional starting value.

### Are there any alternative ways to solve this problem you want to suggest?

```gml
/**
* Executes recursively the function with all nodes.
* 
* @param {Pointer.FlexpanelNode} _root
* @param {Function} _function   Signature : function(_node, _data, _prevResult) { return _newResult; } 
* @param {Any}      _result     The starting result.
* @returns {Any}
*/
function flexpanel_ext_execute(_root, _function, _result=undefined)
{
  // Execute child-nodes first.
  var _count = flexpanel_node_get_num_children(_root);
  for(var i = 0; i < _count; i++)
  {
    var _node = flexpanel_node_get_child(_root, i);
    _result = flexpanel_ext_execute(_node, _function, _result);
  }

  // Execute with root.
  var _data = flexpanel_node_get_data(_root);
  return _function(_root, _data, _result);
}




/**
* Executes recursively the function upward in parent nodes.
* 
* @param {Pointer.FlexpanelNode} _node
* @param {Function} _function   Signature : function(_node, _data, _prevResult) { return _newResult; } 
* @param {Any}      _result     The starting result.
* @returns {Any}
*/
function flexpanel_ext_execute_upward(_node, _function, _result=undefined)
{
  // Execute with given.
  var _data = flexpanel_node_get_data(_node);
  _result = _function(_node, _data, _result);

  // Check for parent and execute with it.
  var _parent = flexpanel_node_get_parent(_node);
  if (_parent != undefined)
  {
    _result = flexpanel_ext_execute_upward(_parent, _function, _result);
  }

  // Return the final result.
  return _result;
}
