1.1 链表实现与操作
链表是计算机科学中最基础的数据结构之一，下面我们实现一个完整的双向链表：

class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.length = 0

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            new_node.prev = self.tail
            self.tail = new_node
        self.length += 1

    def prepend(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node
        self.length += 1

    def insert_at(self, index, data):
        if index < 0 or index > self.length:
            raise IndexError("Index out of range")

        if index == 0:
            return self.prepend(data)
        if index == self.length:
            return self.append(data)

        new_node = Node(data)
        leader = self.traverse_to_index(index-1)
        follower = leader.next

        leader.next = new_node
        new_node.prev = leader
        new_node.next = follower
        follower.prev = new_node

        self.length += 1

    def remove_at(self, index):
        if index < 0 or index >= self.length:
            raise IndexError("Index out of range")

        if index == 0:
            self.head = self.head.next
            if self.head:
                self.head.prev = None
            else:
                self.tail = None
        elif index == self.length-1:
            self.tail = self.tail.prev
            self.tail.next = None
        else:
            leader = self.traverse_to_index(index-1)
            unwanted_node = leader.next
            leader.next = unwanted_node.next
            leader.next.prev = leader

        self.length -= 1

    def traverse_to_index(self, index):
        if index < 0 or index >= self.length:
            raise IndexError("Index out of range")

        counter = 0
        current = self.head
        while counter != index:
            current = current.next
            counter += 1
        return current

    def print_list(self):
        current = self.head
        while current:
            print(current.data, end=" <-> ")
            current = current.next
        print("None")
        print(f"Length: {self.length}")

# 使用示例
dll = DoublyLinkedList()
dll.append(10)
dll.append(20)
dll.prepend(5)
dll.insert_at(2, 15)
dll.print_list()  # 输出: 5 <-> 10 <-> 15 <-> 20 <-> None
dll.remove_at(1)
dll.print_list()  # 输出: 5 <-> 15 <-> 20 <-> None
1.2 哈希表实现
哈希表是实现高效查找的重要数据结构：

class HashTable:
    def __init__(self, size=50):
        self.size = size
        self.table = [[] for _ in range(size)]

    def _hash(self, key):
        return hash(key) % self.size

    def set(self, key, value):
        hash_key = self._hash(key)
        bucket = self.table[hash_key]

        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return

        bucket.append((key, value))

    def get(self, key):
        hash_key = self._hash(key)
        bucket = self.table[hash_key]

        for k, v in bucket:
            if k == key:
                return v

        raise KeyError(key)

    def delete(self, key):
        hash_key = self._hash(key)
        bucket = self.table[hash_key]

        for i, (k, v) in enumerate(bucket):
            if k == key:
                del bucket[i]
                return

        raise KeyError(key)

    def __str__(self):
        return str(self.table)

# 使用示例
ht = HashTable()
ht.set("name", "Alice")
ht.set("age", 25)
ht.set("city", "New York")
print(ht.get("name"))  # 输出: Alice
ht.set("name", "Bob")
print(ht.get("name"))  # 输出: Bob
ht.delete("city")
try:
    print(ht.get("city"))
except KeyError as e:
    print(f"Key not found: {e}")
